def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        limit = int(n ** 0.5) + 1
        for j in range(3, limit, 2):
            if n % j == 0:
                return False
        return True

    # generate list of primes up to 100 once
    primes = [p for p in range(2, 101) if is_prime(p)]

    for i in primes:
        for j in primes:
            for k in primes:
                if i * j * k == a:
                    return True
    return False
